package com.sharehope.event.model;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.*; import java.util.*;
@Entity @Table(name="events") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Event { @Id private UUID id; @Column(nullable=false,unique=true) private String slug; @Column(nullable=false) private String category; @Column(nullable=false) private OffsetDateTime startAt; private OffsetDateTime endAt; @Column(nullable=false) private String timezone; @Column(columnDefinition="text") private String location; @Column(columnDefinition="text") private String virtualUrl; @Column(columnDefinition="text") private String imageUrl; @Column(nullable=false) private Integer displayOrder; @Column(nullable=false) private String status; @Column(nullable=false) private Boolean featured; @Column(nullable=false) private Boolean highlighted; private Integer capacity; @Column(nullable=false) private Boolean enableRsvp; @Column(nullable=false) private Boolean enableDonate; @Column(nullable=false) private Boolean enableVolunteer; @JdbcTypeCode(SqlTypes.JSON) @Column(columnDefinition="jsonb",nullable=false) @Builder.Default private Map<String,Object> translations=new HashMap<>(); @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; @PrePersist void create(){var now=OffsetDateTime.now();if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=now;updatedAt=now;if(displayOrder==null)displayOrder=0;if(status==null)status="DRAFT";if(featured==null)featured=false;if(highlighted==null)highlighted=false;if(enableRsvp==null)enableRsvp=true;if(enableDonate==null)enableDonate=true;if(enableVolunteer==null)enableVolunteer=true;} @PreUpdate void update(){updatedAt=OffsetDateTime.now();} }
